use stable.herd;
use stable.ledger;

fn fed_entries(ponies: List<stable.herd.Pony>, i: Int, acc: List<String>) -> List<String> {
    match ponies.get(index: i) {
        Some(p) => {
            let fed = stable.herd.feed(pony: p, scoops: 3);
            let entry = stable.ledger.entry(pony: fed);
            fed_entries(ponies: ponies, i: i + 1, acc: acc.concat(other: [entry]))
        }
        None => acc,
    }
}

fn main(io: Io) -> Result<Unit, Error> uses {Io.write} {
    let entries = fed_entries(ponies: stable.herd.lineup(), i: 0, acc: []);
    io.write(text: entries.join(sep: ","))?;
    return Ok(unit);
}

