use relay.feed;

pub fn publish(io: Io) -> Result<Unit, Error> uses {Io.write} {
    let frames = relay.feed.frames();
    var total = 0;
    var i = 0;
    while i < frames.len() {
        let value = match frames.get(index: i) {
            Some(frame) => match relay.feed.decode(frame: frame) {
                Ok(decoded) => decoded,
                Err(_) => 0,
            },
            None => 0,
        };
        total = total + value;
        i = i + 1;
    }
    relay.feed.emit(io: io, total: total)?;
    return Ok(unit);
}

fn main(io: Io) -> Result<Unit, Error> uses {Io.write} {
    let board = galley.menu.board();
    var index = 0;
    while index < board.len() {
        let sep = match index > 0 {
            true => ";",
            false => "",
        };
        io.write(text: sep)?;
        let dish = match board.get(index: index) {
            Some(d) => d,
            None => return Ok(unit),
        };
        galley.kitchen.serve(io: io, dish: dish)?;
        index = index + 1;
    }
    return Ok(unit);
}

