use mill.stock;
use mill.rules;

pub fn lines() -> String {
    let planks = mill.stock.inventory();
    var kept_labels: List<String> = [];
    var i = 0;
    while i < planks.len() {
        let maybe_plank = planks.get(index: i);
        match maybe_plank {
            Some(p) => {
                if mill.rules.keeps(plank: p) {
                    kept_labels.push(item: mill.rules.label(plank: p));
                }
            }
            None => {}
        }
        i = i + 1;
    }
    kept_labels.join(sep: ",")
}
